function canAccess(page){
  if(!SESSION) return false;
  const allowed = PAGE_ACCESS[page] || [];
  return allowed.includes(SESSION.role);
}

// ---------- AUTH ----------
function handleLogin(ev){
  ev.preventDefault();
  const u = document.getElementById('loginUser').value.trim();
  const p = document.getElementById('loginPass').value;
  const err = document.getElementById('loginError');
  const user = DB.users.find(x=>x.username.toLowerCase()===u.toLowerCase() && x.password===p);
  if(!user){
    err.textContent = 'Username atau password salah.';
    return false;
  }
  if(user.status !== 'Aktif'){
    err.textContent = 'Akun ini tidak aktif. Hubungi Owner.';
    return false;
  }
  SESSION = {username:user.username, role:user.role};
  sessionStorage.setItem('erp_session', JSON.stringify(SESSION));
  err.textContent = '';
  enterApp();
  return false;
}
function logout(){
  SESSION = null;
  sessionStorage.removeItem('erp_session');
  document.getElementById('app').classList.remove('active');
  document.getElementById('loginScreen').style.display = 'flex';
  document.getElementById('loginForm').reset();
}
function enterApp(){
  document.getElementById('loginScreen').style.display = 'none';
  document.getElementById('app').classList.add('active');
  document.getElementById('roleTag').textContent = SESSION.role;
  document.getElementById('userInfo').innerHTML = `Masuk sebagai<br><b>${esc(SESSION.username)}</b>`;
  buildNav();
  navigateTo('dashboard');
  updateClock();
  setInterval(updateClock, 60000);
}
function updateClock(){
  const el = document.getElementById('topDate');
  const now = new Date();
  el.textContent = now.toLocaleDateString('id-ID',{weekday:'long', day:'2-digit', month:'long', year:'numeric'});
}

// ---------- NAVIGATION ----------
function buildNav(){
  document.querySelectorAll('.nav-item').forEach(item=>{
    const page = item.dataset.page;
    if(!canAccess(page)){
      item.style.display = 'none';
    } else {
      item.style.display = 'flex';
      item.onclick = ()=>navigateTo(page);
    }
  });
  // hide user mgmt group entirely if not owner
  document.getElementById('navUserMgmt').style.display = (SESSION.role==='OWNER') ? 'block':'none';
}

function navigateTo(page){
  if(!canAccess(page)){
    showToast('Anda tidak memiliki akses ke menu ini.');
    return;
  }
  currentPage = page;
  document.querySelectorAll('.nav-item').forEach(i=>i.classList.toggle('active', i.dataset.page===page));
  document.getElementById('topTitle').textContent = PAGE_TITLES[page];
  document.getElementById('topBreadcrumb').textContent = PAGE_BREADCRUMB[page];
  renderPage(page);
  toggleSidebar(false);
  document.getElementById('content').scrollTop = 0;
}

// ---------- MOBILE SIDEBAR DRAWER ----------
function toggleSidebar(force){
  const sb = document.getElementById('sidebarEl');
  const overlay = document.getElementById('sidebarOverlay');
  const open = (force === undefined) ? !sb.classList.contains('open') : force;
  sb.classList.toggle('open', open);
  overlay.classList.toggle('show', open);
}

function renderPage(page){
  const content = document.getElementById('content');
  const renderers = {
    dashboard: renderDashboard,
    pembelian: renderPembelian,
    produksi: renderProduksi,
    penjualan: renderPenjualan,
    gudang: renderGudang,
    bahanpendukung: renderBahanPendukung,
    distribusi: renderDistribusi,
    kasbank: renderKasBank,
    hutangpiutang: renderHutangPiutang,
    labarugi: renderLabaRugi,
    neraca: renderNeraca,
    laporan: renderLaporan,
    supplier: ()=>renderMasterTable('supplier'),
    pelanggan: ()=>renderMasterTable('pelanggan'),
    jenisgabah: ()=>renderSimpleList('jenisGabah'),
    jenisberas: ()=>renderSimpleList('jenisBeras'),
    jenissamping: ()=>renderSimpleList('jenisSamping'),
    jenisbahanbaku: ()=>renderSimpleList('jenisBahanBaku'),
    kendaraan: renderKendaraan,
    usermgmt: renderUserMgmt,
  };
  content.innerHTML = '<div class="page active" id="pageInner"></div>';
  const target = document.getElementById('pageInner');
  (renderers[page] || (()=>{target.innerHTML='<div class="empty-state">Halaman tidak ditemukan.</div>';}))(target);
  // Add dual scroll bar to all table-wraps after render
  setTimeout(initDualScroll, 50);
}

// Injects a mirror scroll bar ABOVE each .table-wrap so user can scroll
// horizontally without having to reach the bottom of a long table.
function initDualScroll(){
  document.querySelectorAll('.table-wrap').forEach(wrap=>{
    // Skip if already has dual scroll, or table isn't actually wider than container
    if(wrap.dataset.dualScrollDone) return;
    wrap.dataset.dualScrollDone = '1';

    const top = document.createElement('div');
    top.className = 'table-scroll-top';
    top.style.cssText = 'overflow-x:auto; overflow-y:hidden; height:12px; margin-bottom:2px;';

    const inner = document.createElement('div');
    inner.style.height = '1px';
    top.appendChild(inner);
    wrap.parentNode.insertBefore(top, wrap);

    // Set inner width to match the actual table scroll width
    function syncWidth(){
      inner.style.width = wrap.scrollWidth + 'px';
      // Hide top bar if no horizontal scroll needed
      top.style.display = wrap.scrollWidth > wrap.clientWidth ? 'block' : 'none';
    }
    syncWidth();

    // Sync scroll positions bidirectionally
    let syncing = false;
    top.addEventListener('scroll', ()=>{
      if(syncing) return;
      syncing = true;
      wrap.scrollLeft = top.scrollLeft;
      syncing = false;
    });
    wrap.addEventListener('scroll', ()=>{
      if(syncing) return;
      syncing = true;
      top.scrollLeft = wrap.scrollLeft;
      syncing = false;
    });

    // Re-sync width on window resize
    window.addEventListener('resize', syncWidth, {passive:true});
  });
}

// ---------- MODAL ----------
function openModal(html){
  document.getElementById('modalBody').innerHTML = html;
  document.getElementById('modalOverlay').classList.add('show');
}
function closeModal(){
  document.getElementById('modalOverlay').classList.remove('show');
  document.getElementById('modalBody').innerHTML = '';
}
document.addEventListener('click', (e)=>{
  if(e.target.id === 'modalOverlay') closeModal();
});

// ---------- INIT ----------
window.addEventListener('DOMContentLoaded', ()=>{
  loadDB();
  document.getElementById('loginLogo').src = LOGO_DATA_URI;
  document.getElementById('sidebarLogo').src = LOGO_DATA_URI;
  registerServiceWorker();
  const sess = sessionStorage.getItem('erp_session');
  if(sess){
    try{
      SESSION = JSON.parse(sess);
      // validate user still exists/active
      const user = DB.users.find(x=>x.username===SESSION.username);
      if(user && user.status==='Aktif'){
        enterApp();
        return;
      }
    }catch(e){}
  }
});

// ---------- PWA: SERVICE WORKER & INSTALL PROMPT ----------
let deferredInstallPrompt = null;

function registerServiceWorker(){
  if('serviceWorker' in navigator){
    // Service workers require https or localhost; silently no-op on file:// or unsupported contexts
    if(location.protocol === 'file:'){
      console.info('Service worker dilewati: buka aplikasi via http/https (atau "Install" dari browser) untuk dukungan offline penuh.');
      return;
    }
    navigator.serviceWorker.register('./sw.js').catch((err)=>{
      console.warn('Gagal mendaftarkan service worker:', err);
    });
  }
}

window.addEventListener('beforeinstallprompt', (e)=>{
  e.preventDefault();
  deferredInstallPrompt = e;
  const btn = document.getElementById('installAppBtn');
  const btnLogin = document.getElementById('installAppBtnLogin');
  if(btn) btn.style.display = 'block';
  if(btnLogin) btnLogin.style.display = 'block';
});

function installApp(){
  if(!deferredInstallPrompt){
    showToast('Aplikasi sudah terpasang, atau gunakan menu "Install App" pada browser.');
    return;
  }
  deferredInstallPrompt.prompt();
  deferredInstallPrompt.userChoice.then((choice)=>{
    if(choice.outcome === 'accepted'){
      showToast('Aplikasi sedang dipasang...');
    }
    deferredInstallPrompt = null;
    const btn = document.getElementById('installAppBtn');
    const btnLogin = document.getElementById('installAppBtnLogin');
    if(btn) btn.style.display = 'none';
    if(btnLogin) btnLogin.style.display = 'none';
  });
}

window.addEventListener('appinstalled', ()=>{
  showToast('Aplikasi berhasil dipasang.');
  const btn = document.getElementById('installAppBtn');
  const btnLogin = document.getElementById('installAppBtnLogin');
  if(btn) btn.style.display = 'none';
  if(btnLogin) btnLogin.style.display = 'none';
});

// ---------- EXPORT / IMPORT ----------
function exportData(){
  const blob = new Blob([JSON.stringify(DB,null,2)], {type:'application/json'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'erp_padi_data_'+todayStr()+'.json';
  a.click();
  URL.revokeObjectURL(url);
  showToast('Data berhasil diekspor.');
}
function importData(ev){
  const file = ev.target.files[0];
  if(!file) return;
  const reader = new FileReader();
  reader.onload = (e)=>{
    try{
      const data = JSON.parse(e.target.result);
      if(!data.users || !data.pembelian){ throw new Error('Format tidak valid'); }
      DB = data;
      saveDB();
      showToast('Data berhasil diimpor.');
      navigateTo(currentPage);
    }catch(err){
      alert('Gagal mengimpor data: file tidak valid.');
    }
  };
  reader.readAsText(file);
  ev.target.value = '';
}

