function editMaster(kind, idx){
  const cfg = MASTER_CONFIG[kind];
  const isNew = idx === -1;
  const row = isNew ? {} : DB[cfg.list][idx];
  const fieldsHtml = cfg.fields.map(f=>`
    <div class="field">
      <label>${f.label}${f.required?' *':''}</label>
      <input type="${f.type}" id="mf_${f.key}" value="${esc(row[f.key]||'')}" ${f.required?'required':''}>
    </div>
  `).join('');

  openModal(`
    <h2>${isNew?'Tambah':'Ubah'} ${cfg.title}</h2>
    <div class="modal-sub">${isNew? 'Kode akan dibuat otomatis.' : 'Kode: '+esc(row.kode)}</div>
    ${fieldsHtml}
    <div class="form-actions">
      <button class="btn btn-primary" style="width:auto;" onclick="saveMaster('${kind}', ${idx})">Simpan</button>
      <button class="btn btn-secondary" onclick="closeModal()">Batal</button>
    </div>
  `);
}

function saveMaster(kind, idx){
  const cfg = MASTER_CONFIG[kind];
  const data = {};
  for(const f of cfg.fields){
    const val = document.getElementById('mf_'+f.key).value.trim();
    if(f.required && !val){
      alert(f.label+' wajib diisi.');
      return;
    }
    data[f.key] = val;
  }
  if(idx === -1){
    data.kode = cfg.codePrefix + '-' + String(DB[cfg.list].length+1).padStart(3,'0');
    DB[cfg.list].push(data);
  } else {
    data.kode = DB[cfg.list][idx].kode;
    DB[cfg.list][idx] = data;
  }
  saveDB();
  closeModal();
  showToast('Data tersimpan.');
  renderMasterTable(kind);
}

function deleteMaster(kind, idx){
  const cfg = MASTER_CONFIG[kind];
  if(!confirm('Hapus data ini? Tindakan tidak dapat dibatalkan.')) return;
  DB[cfg.list].splice(idx,1);
  saveDB();
  renderMasterTable(kind);
  showToast('Data dihapus.');
}

