/* ============================================================
   EXCEL EXPORT (via SheetJS)
   Converts the <table> inside the given container element to an
   .xlsx file. Action buttons inside the table (if any) are
   stripped before export.
   ============================================================ */
function exportTableToExcel(sourceElId, filenamePrefix, sheetName){
  const source = document.getElementById(sourceElId);
  if(!source){ showToast('Konten tabel tidak ditemukan.'); return; }
  if(typeof XLSX === 'undefined'){
    showToast('Fitur Excel membutuhkan koneksi internet (memuat library) saat dibuka pertama kali.');
    return;
  }
  const table = source.querySelector('table');
  if(!table){ showToast('Tabel tidak ditemukan.'); return; }

  // Clone and strip interactive elements (buttons) so only text data is exported
  const clone = table.cloneNode(true);
  clone.querySelectorAll('button, .empty-state').forEach(el=>el.remove());
  // Remove empty rows left after stripping action-only cells
  clone.querySelectorAll('tr').forEach(tr=>{
    const cells = tr.querySelectorAll('td');
    if(cells.length===1 && cells[0].textContent.trim()===''){ tr.remove(); }
  });

  try{
    const wb = XLSX.utils.table_to_book(clone, {sheet: (sheetName||'Laporan').slice(0,31)});
    const filename = filenamePrefix + '_' + todayStr() + '.xlsx';
    XLSX.writeFile(wb, filename);
    showToast('Excel berhasil diunduh.');
  }catch(e){
    console.error(e);
    showToast('Gagal membuat file Excel.');
  }
}


