  const totalBeras = DB.produksi.reduce((s,r)=>s+Number(r.premium||0)+Number(r.medium||0),0);
  const avgRendemen = totalGabah>0 ? totalBeras/totalGabah : 0;
  const totalHppNilai = getTotalHPPProduksi();
  const totalBerasSemua = DB.produksi.reduce((s,r)=>s+Number(r.premium||0)+Number(r.medium||0)+Number(r.menir||0)+Number(r.bekatul||0),0);
  const avgHppPerKgBeras = totalBerasSemua>0 ? totalHppNilai/totalBerasSemua : 0;

