// Get available pembelian options for the source picker: matches selected jenisGabah and
// has remaining (unallocated) qty > 0, OR is currently selected in this row (so its full
// qty/harga still show even if fully allocated by this same batch).
function getPembelianOptionsForSumber(jenisGabah, currentPembelianId){
  const editCtx = window._produksiEdit || {sumberGabah:[]};
  return DB.pembelian.filter(p=>{
    if(jenisGabah && p.jenisGabah !== jenisGabah) return false;
    if(p.id === currentPembelianId) return true;
    // sisa available globally (excluding this batch's existing allocations entirely)
    const sisaGlobal = getSisaPembelian(p.id, editCtx.id);
    // subtract qty already reserved by OTHER rows within this same edit session
    const reservedByOtherRows = (editCtx.sumberGabah||[])
      .filter(s=>s.pembelianId===p.id)
      .reduce((sum,s)=>sum+Number(s.qty||0), 0);
    return (sisaGlobal - reservedByOtherRows) > 0;
  });
}

// Toggle antara section Gabah dan section Bahan Baku di form produksi
function updateProduksiBahanForm(){
  const tipe = document.getElementById('pr_tipeBahan')?.value || 'Gabah';
  const gabahSec = document.getElementById('pr_gabah_section');
  const bbSec = document.getElementById('pr_bahanbaku_section');
  if(gabahSec) gabahSec.style.display = tipe==='Gabah' ? '' : 'none';
  if(bbSec) bbSec.style.display = tipe==='Bahan Baku' ? '' : 'none';
}

function renderSumberGabahPicker(){
  const box = document.getElementById('sumberGabahBox');
  if(!box) return;
  const jenisGabah = document.getElementById('pr_jenis').value;
  const ctx = window._produksiEdit;
  const sumber = ctx.sumberGabah;

  if(sumber.length===0){
    box.innerHTML = `<div class="help-text" style="margin:8px 0;">Belum ada sumber gabah dipilih. Klik "+ Tambah Sumber Gabah" untuk menambahkan, atau biarkan kosong jika tidak melacak HPP per batch ini.</div>`;
    updateHppPreview();
    return;
  }

  box.innerHTML = `
    <div class="table-wrap">
      <table>
        <thead><tr><th>Pembelian (Faktur - Supplier)</th><th>Sisa Tersedia</th><th>Harga/Kg (+angkut)</th><th>Qty Dipakai (Kg)</th><th></th></tr></thead>
        <tbody>
          ${sumber.map((s,i)=>{
            const opts = getPembelianOptionsForSumber(jenisGabah, s.pembelianId);
            const optionsHtml = ['<option value="">-- Pilih Pembelian --</option>'].concat(
              opts.map(p=>{
                const reservedByOthers = sumber.filter((x,xi)=>xi!==i && x.pembelianId===p.id).reduce((sum,x)=>sum+Number(x.qty||0),0);
                const sisa = getSisaPembelian(p.id, ctx.id) - reservedByOthers;
                const hargaEf = getHargaEfektifPembelian(p);
                return `<option value="${p.id}" ${s.pembelianId===p.id?'selected':''}>${esc(p.noFaktur)} - ${esc(p.supplier)} (sisa ${fmtNum(sisa)} kg @ ${fmtRp(hargaEf)})</option>`;
              })
            ).join('');
            const p = DB.pembelian.find(x=>x.id===s.pembelianId);
            const reservedByOthersForCurrent = p ? sumber.filter((x,xi)=>xi!==i && x.pembelianId===p.id).reduce((sum,x)=>sum+Number(x.qty||0),0) : 0;
            const sisaTampil = p ? getSisaPembelian(p.id, ctx.id) - reservedByOthersForCurrent : 0;
            const hargaTampil = p ? getHargaEfektifPembelian(p) : 0;
            return `
              <tr>
                <td><select onchange="updateSumberGabah(${i}, 'pembelianId', this.value)" style="width:100%;">${optionsHtml}</select></td>
                <td class="num-cell">${p?fmtNum(sisaTampil)+' kg':'-'}</td>
                <td class="num-cell">${p?fmtRp(hargaTampil):'-'}</td>
                <td><input type="number" min="0" value="${s.qty||0}" style="width:100%;" oninput="updateSumberGabah(${i}, 'qty', this.value)"></td>
                <td><button class="btn btn-sm btn-danger" onclick="removeSumberGabahRow(${i})">✕</button></td>
              </tr>
            `;
          }).join('')}
        </tbody>
      </table>
    </div>
  `;
  updateHppPreview();
}

function addSumberGabahRow(){
  const ctx = window._produksiEdit;
  ctx.sumberGabah.push({pembelianId:'', qty:0, harga:0});
  renderSumberGabahPicker();
}
function removeSumberGabahRow(idx){
  const ctx = window._produksiEdit;
  ctx.sumberGabah.splice(idx,1);
  renderSumberGabahPicker();
}
function updateSumberGabah(idx, field, value){
  const ctx = window._produksiEdit;
  const row = ctx.sumberGabah[idx];
  if(field==='pembelianId'){
    row.pembelianId = value;
    const p = DB.pembelian.find(x=>x.id===value);
    row.harga = p ? getHargaEfektifPembelian(p) : 0;
    // auto-fill qty with remaining available (capped) if currently 0
    if(p && !row.qty){
      const sisa = getSisaPembelian(p.id, ctx.id);
      const gabahTarget = Number(document.getElementById('pr_gabah').value)||0;
      const usedSoFar = ctx.sumberGabah.reduce((s,x,i)=> i===idx?s:s+Number(x.qty||0), 0);
      row.qty = Math.max(0, Math.min(sisa, gabahTarget - usedSoFar));
    }
  } else if(field==='qty'){
    row.qty = Number(value)||0;
  }
  renderSumberGabahPicker();
}

function updateHppPreview(){
  const ctx = window._produksiEdit;
  const gabah = Number(document.getElementById('pr_gabah')?.value)||0;
  const premium = Number(document.getElementById('pr_premium')?.value)||0;
  const medium = Number(document.getElementById('pr_medium')?.value)||0;
  const menir = Number(document.getElementById('pr_menir')?.value)||0;
  const bekatul = Number(document.getElementById('pr_bekatul')?.value)||0;
  const totalBeras = premium+medium+menir+bekatul;

  let totalNilai = 0, totalQty = 0;
  ctx.sumberGabah.forEach(s=>{
    if(!s.pembelianId) return;
    totalNilai += Number(s.qty||0)*Number(s.harga||0);
    totalQty += Number(s.qty||0);
  });

  const hppGabahEl = document.getElementById('pr_hpp_gabah_display');
  const hppBerasEl = document.getElementById('pr_hpp_beras_display');
  if(!hppGabahEl || !hppBerasEl) return;

  if(totalQty<=0){
    hppGabahEl.value = '-';
    hppBerasEl.value = '-';
    return;
  }
  const hppPerKgGabah = totalNilai/totalQty; // weighted average price of sources picked
  const hppPerKgBeras = totalBeras>0 ? totalNilai/totalBeras : 0;
  hppGabahEl.value = fmtRp(hppPerKgGabah) + '/kg';
  hppBerasEl.value = totalBeras>0 ? fmtRp(hppPerKgBeras)+'/kg' : '-';

  // warn if sumber qty doesn't match gabah masuk
  const note = document.getElementById('sumberGabahNote');
  if(note) note.remove();
}
function validateSumberGabah(){
  updateHppPreview();
}
function calcRendemenPreview(){
  const gabah = Number(document.getElementById('pr_gabah').value)||0;
  const premium = Number(document.getElementById('pr_premium').value)||0;
  const medium = Number(document.getElementById('pr_medium').value)||0;
  const rendemen = gabah>0 ? ((premium+medium)/gabah)*100 : 0;
  document.getElementById('pr_rendemen_display').value = rendemen.toFixed(1)+'%';
  updateHppPreview();
}

function saveProduksi(id, isNew){
  const mulai = document.getElementById('pr_mulai').value;
  const selesai = document.getElementById('pr_selesai').value;
  const operator = document.getElementById('pr_operator').value.trim();
  const tipeBahan = document.getElementById('pr_tipeBahan')?.value || 'Gabah';
  const premium = Number(document.getElementById('pr_premium').value)||0;
  const medium = Number(document.getElementById('pr_medium').value)||0;
  const menir = Number(document.getElementById('pr_menir').value)||0;
  const bekatul = Number(document.getElementById('pr_bekatul').value)||0;
  const gabah = Number(document.getElementById('pr_gabah').value)||0;

  if(!mulai || !selesai){
    alert('Tanggal Mulai dan Selesai wajib diisi.');
    return;
  }
  if(selesai < mulai){
    alert('Tanggal Selesai tidak boleh sebelum Tanggal Mulai.');
    return;
  }

  // ---- Bahan Baku (Pecah Kulit) mode ----
  if(tipeBahan === 'Bahan Baku'){
    const jenisBahanBaku = document.getElementById('pr_jenisBahanBaku').value;
    const hppBahanBaku = readInputRp('pr_hpp_bb');
    if(!jenisBahanBaku || gabah<=0){
      alert('Jenis Bahan Baku dan Qty masuk wajib diisi.');
      return;
    }
    const ctx = window._produksiEdit;
    if(isNew){
      DB.produksi.push({id, batch: nextCode('batch','BTC',3), mulai, selesai, operator,
        tipeBahan:'Bahan Baku', jenisBahanBaku, jenisGabah:jenisBahanBaku,
        gabah, premium, medium, menir, bekatul, hppBahanBaku, sumberGabah:[]});
    } else {
      const row = DB.produksi.find(r=>r.id===id);
      Object.assign(row, {mulai, selesai, operator,
        tipeBahan:'Bahan Baku', jenisBahanBaku, jenisGabah:jenisBahanBaku,
        gabah, premium, medium, menir, bekatul, hppBahanBaku});
    }
    saveDB(); closeModal();
    showToast('Batch produksi (Bahan Baku) tersimpan.');
    renderProduksi(); return;
  }

  // ---- Gabah mode (existing logic) ----
  const jenisGabah = document.getElementById('pr_jenis').value;
  if(!jenisGabah || gabah<=0){
    alert('Jenis Gabah dan Gabah Masuk wajib diisi dengan benar.');
    return;
  }

  // Validate sumber gabah
  const ctx = window._produksiEdit;
  const sumberGabah = (ctx.sumberGabah||[]).filter(s=>s.pembelianId && Number(s.qty||0)>0);
  const totalSumberQty = sumberGabah.reduce((s,x)=>s+Number(x.qty||0),0);

  if(sumberGabah.length>0){
    for(const s of sumberGabah){
      const sisa = getSisaPembelian(s.pembelianId, id);
      const usedByOtherRowsThisBatch = sumberGabah.filter(x=>x!==s && x.pembelianId===s.pembelianId).reduce((sum,x)=>sum+Number(x.qty||0),0);
      if(Number(s.qty||0) + usedByOtherRowsThisBatch > sisa){
        const p = DB.pembelian.find(x=>x.id===s.pembelianId);
        alert(`Qty sumber gabah dari faktur ${p?p.noFaktur:'?'} melebihi sisa yang tersedia (${fmtNum(sisa)} kg).`);
        return;
      }
    }
    if(Math.abs(totalSumberQty - gabah) > 0.01){
      if(!confirm(`Total qty sumber gabah (${fmtNum(totalSumberQty)} kg) tidak sama dengan Gabah Masuk Giling (${fmtNum(gabah)} kg). HPP akan dihitung berdasarkan total sumber yang dipilih. Lanjutkan simpan?`)){
        return;
      }
    }
  }

  if(isNew){
    DB.produksi.push({id, batch: nextCode('batch','BTC',3), mulai, selesai, operator,
      tipeBahan:'Gabah', jenisGabah, gabah, premium, medium, menir, bekatul, sumberGabah});
  } else {
    const row = DB.produksi.find(r=>r.id===id);
    Object.assign(row, {mulai, selesai, operator, tipeBahan:'Gabah', jenisGabah, gabah, premium, medium, menir, bekatul, sumberGabah});
  }
  saveDB();
  closeModal();
  delete window._produksiEdit;
  showToast('Batch produksi tersimpan.');
  renderProduksi();
}

function deleteProduksi(id){
  if(!confirm('Hapus batch produksi ini?')) return;
  DB.produksi = DB.produksi.filter(r=>r.id!==id);
  saveDB();
  renderProduksi();
  showToast('Batch dihapus.');
}

/* ============================================================
   KAS & BANK SYNC HELPERS
   Each transaction (pembelian/penjualan) maintains a linked
   kasbank entry tagged with sumber type + sourceId, so edits
   and deletes stay in sync automatically.
   ============================================================ */
function syncKasBankEntry(sumberType, sourceId, entry){
  let existing = DB.kasbank.find(k=>k.sumber===sumberType && k.sourceId===sourceId);
  if(!existing){
    existing = {id: uid(), sumber:sumberType, sourceId};
    DB.kasbank.push(existing);
  }
  Object.assign(existing, entry);
}
function removeKasBankEntry(sumberType, sourceId){
  DB.kasbank = DB.kasbank.filter(k=>!(k.sumber===sumberType && k.sourceId===sourceId));
}

