function updateKirimBertahapNote(){
  const checked = document.getElementById('pj_kirim_bertahap').checked;
  const note = document.getElementById('pj_kirim_bertahap_note');
  note.textContent = checked
    ? 'Stok gudang baru akan berkurang saat status pengiriman di Distribusi & Pengiriman diubah menjadi "Terkirim" (per trip), bukan saat transaksi ini disimpan.'
    : 'Stok gudang berkurang penuh sesuai Qty saat transaksi ini disimpan (pengiriman dianggap sekali, langsung tuntas).';
}
function getPenjualanProdukOptions(kategori, selected){
  if(kategori==='Gabah'){
    return DB.jenisGabah.map(j=>`<option value="${esc(j)}" ${j===selected?'selected':''}>${esc(j)}</option>`).join('');
  }
  if(kategori==='Produk Samping'){
    const list = DB.jenisSamping||[];
    if(list.length===0) return `<option value="">-- Tambahkan di Master Produk Samping --</option>`;
    return list.map(p=>`<option value="${esc(p)}" ${p===selected?'selected':''}>${esc(p)}</option>`).join('');
  }
  // Beras Utama: semua dari jenisBeras
  const list = DB.jenisBeras||[];
  if(list.length===0) return `<option value="">-- Tambahkan di Master Jenis Beras --</option>`;
  return list.map(p=>{
    const label = p==='Premium'?'Beras Premium':p==='Medium'?'Beras Medium':p;
    return `<option value="${esc(p)}" ${p===selected?'selected':''}>${esc(label)}</option>`;
  }).join('');
}
// Beras utama default = Premium & Medium. Used for stok display separation.
const PRODUK_BERAS_UTAMA = ['Premium','Medium'];

// Build per-item KPI cards for produk samping
// source: array of pembelian/penjualan records with kategori='Produk Samping'
// itemKey: 'jenisGabah' (pembelian) or 'produk' (penjualan)
function buildSampingKpiCards(records, itemKey, borderColor){
  if(!records || records.length===0) return '';
  // Group by item
  const byItem = {};
  records.forEach(r=>{
    const item = r[itemKey]||'-';
    if(!byItem[item]) byItem[item] = {qty:0, nilai:0, count:0};
    byItem[item].qty   += Number(r.qty||0);
    byItem[item].nilai += Number(r.total||0);
    byItem[item].count += 1;
  });
  return Object.entries(byItem).map(([item, v])=>`
    <div class="kpi" style="border-left-color:${borderColor||'#0EA5E9'};">
      <div class="label">${esc(item)}</div>
      <div class="value" style="font-size:1.15rem;">${fmtNum(v.qty)} <span style="font-size:0.85rem;">kg</span></div>
      <div class="sub">Nilai: ${fmtRp(v.nilai)} · ${v.count} transaksi</div>
    </div>
  `).join('');
}

// Build per-item stok KPI for produk samping from getStokProduk()
function buildSampingStokKpiCards(stok){
  const jenisSamping = DB.jenisSamping||[];
  if(jenisSamping.length===0) return '';
  return jenisSamping.map(item=>{
    const qty = stok[item]||0;
    return `
    <div class="kpi" style="border-left-color:#0EA5E9;">
      <div class="label">Stok ${esc(item)}</div>
      <div class="value" style="font-size:1.15rem;">${fmtNum(qty)} <span style="font-size:0.85rem;">kg</span></div>
    </div>`;
  }).join('');
}

function updatePenjualanKategori(){
  const kategori = document.getElementById('pj_kategori').value;
  const produkSelect = document.getElementById('pj_produk');
  produkSelect.innerHTML = getPenjualanProdukOptions(kategori, null);
  document.getElementById('pj_produk_label').textContent =
    kategori==='Gabah' ? 'Jenis Gabah' :
    kategori==='Produk Samping' ? 'Produk Samping' : 'Produk Beras';
  autoFillHarga();
  updatePenjualanKategoriNote();
}
function updatePenjualanKategoriNote(){
  const kategori = document.getElementById('pj_kategori').value;
  const note = document.getElementById('pj_kategori_note');
  note.textContent =
    kategori==='Gabah' ? 'Menjual gabah langsung tanpa digiling. Stok gabah akan berkurang sesuai qty yang dijual.' :
    kategori==='Produk Samping' ? 'Menjual hasil samping giling: bekatul, menir, sekam, dll. Stok produk samping akan berkurang.' :
    'Menjual beras utama (Premium / Medium) hasil produksi atau pembelian beras langsung.';
}

function autoFillHarga(){
  const kategori = document.getElementById('pj_kategori').value;
  const produk = document.getElementById('pj_produk').value;
  const hintEl = document.getElementById('pj_harga_hint');
  if(!produk){ if(hintEl) hintEl.textContent=''; return; }

  let harga = 0, ref = null;
  if(kategori==='Gabah'){
    const result = getHargaGabahTerakhir(produk);
    harga = result.harga;
  } else {
    const result = getHargaJualTerakhir(produk, kategori);
    harga = result.harga;
    ref = result.ref;
  }

  document.getElementById('pj_harga').value = harga > 0 ? Number(harga).toLocaleString('id-ID') : '';
  calcPenjualanTotal();

  if(hintEl){
    if(ref){
      hintEl.innerHTML = `Referensi harga terakhir: <b>${fmtRp(ref.harga)}/kg</b> ke ${esc(ref.pelanggan)} pada ${fmtDate(ref.tanggal)} (${esc(ref.invoice)}). Bisa diubah manual.`;
    } else if(harga > 0){
      hintEl.innerHTML = `Harga rekomendasi dari default sistem: <b>${fmtRp(harga)}/kg</b>. Bisa diubah manual.`;
    } else {
      hintEl.innerHTML = `Belum ada riwayat harga jual untuk produk ini.`;
    }
  }
}
function calcPenjualanTotal(){
  const qty = readInputRp('pj_qty');
  const harga = readInputRp('pj_harga');
  const diskon = readInputRp('pj_diskon');
  const status = document.getElementById('pj_status').value;
  const total = (qty*harga)-diskon;
  const piutang = status==='Piutang' ? total : 0;
  document.getElementById('pj_total_display').value = fmtRp(total);
  document.getElementById('pj_piutang_display').value = fmtRp(piutang);

  // Stock warning
  const kategori = document.getElementById('pj_kategori').value;
  const produk = document.getElementById('pj_produk').value;
  const stok = kategori==='Gabah' ? getStokGabah() : getStokProduk();
  const satuanLabel = kategori==='Gabah' ? `Gabah ${produk}` : produk;
  const warn = document.getElementById('stokWarning');
  if(qty > (stok[produk]||0)){
    warn.innerHTML = `⚠ Stok ${satuanLabel} saat ini hanya ${fmtNum(stok[produk]||0)} kg. Transaksi tetap bisa disimpan, namun periksa kembali persediaan.`;
    warn.style.color = 'var(--red)';
  } else {
    warn.textContent = '';
  }
}

function savePenjualan(id, isNew){
  const tanggal = document.getElementById('pj_tanggal').value;
  const pelanggan = document.getElementById('pj_pelanggan').value;
  const kategori = document.getElementById('pj_kategori').value;
  const produk = document.getElementById('pj_produk').value;
  const qty = readInputRp('pj_qty');
  const harga = readInputRp('pj_harga');
  const diskon = readInputRp('pj_diskon');
  const status = document.getElementById('pj_status').value;
  const kirimBertahap = document.getElementById('pj_kirim_bertahap').checked;

  if(!tanggal || !pelanggan || qty<=0){
    alert('Tanggal, Pelanggan, dan Qty wajib diisi dengan benar.');
    return;
  }
  const total = (qty*harga)-diskon;
  const piutang = status==='Piutang' ? total : 0;

  let row;
  if(isNew){
    row = {id, tanggal, invoice: nextCode('invoice','INV',4), kategori, pelanggan, produk, qty, harga, diskon, total, piutang, status, kirimBertahap};
    DB.penjualan.push(row);
  } else {
    row = DB.penjualan.find(r=>r.id===id);
    Object.assign(row, {tanggal, kategori, pelanggan, produk, qty, harga, diskon, total, piutang, status, kirimBertahap});
  }

  const kasMasuk = total - piutang;
  const labelBarang = kategori==='Gabah' ? `gabah ${esc(produk)}` : esc(produk);
  syncKasBankEntry('penjualan', row.id, {
    tanggal, keterangan:`Penjualan ${labelBarang} kepada ${esc(pelanggan)} (${row.invoice})`,
    masuk:kasMasuk, keluar:0, kategori: kategori==='Gabah' ? 'Penjualan Gabah' : 'Penjualan Barang Jadi'
  });

  saveDB();
  closeModal();
  showToast('Transaksi penjualan tersimpan.');
  renderPenjualan();
}

function deletePenjualan(id){
  if(!confirm('Hapus transaksi penjualan ini? Semua catatan kas terkait (penerimaan, pelunasan piutang) juga akan dihapus.')) return;
  DB.penjualan = DB.penjualan.filter(r=>r.id!==id);
  // Hapus: (1) entry utama penjualan
  DB.kasbank = DB.kasbank.filter(k=>!(k.sumber==='penjualan' && k.sourceId===id));
  // Hapus: (2) entry Penerimaan Pelunasan Piutang yang terhubung via refId
  DB.kasbank = DB.kasbank.filter(k=>!(k.kategori==='Penerimaan Pelunasan Piutang' && k.refId===id));
  saveDB();
  renderPenjualan();
  showToast('Transaksi dan semua catatan kas terkait dihapus.');
}

